/// Export `WorldTooltip` with a guest-owned string result buffer.
/// The handler receives the flattened query arguments followed by `&mut [u8]`
/// and returns the number of UTF-8 bytes written. The host copies those bytes
/// immediately after the single guest call; no guest pointer is retained.
#[macro_export]
macro_rules! export_world_tooltip {
    ($handler:path, $bytes:expr) => {
        #[repr(align(8))]
        struct __SpringCoreStringResultBuffer_world_tooltip([u8; $bytes]);
        static mut __SPRING_CORE_STRING_RESULT_BUFFER_WORLD_TOOLTIP: __SpringCoreStringResultBuffer_world_tooltip = __SpringCoreStringResultBuffer_world_tooltip([0; $bytes]);

        #[cfg(target_arch = "wasm32")]
        #[export_name = "spring:callin/world-tooltip"]
        pub extern "C" fn __spring_wasm_core_callin_world_tooltip(
            kind: i32,
            unit_id: i32,
            feature_id: i32,
            ground_pos_x: f32,
            ground_pos_y: f32,
            ground_pos_z: f32
        ) -> i64 {
            let pointer = core::ptr::addr_of_mut!(__SPRING_CORE_STRING_RESULT_BUFFER_WORLD_TOOLTIP.0).cast::<u8>();
            if $bytes > u32::MAX as usize || pointer as usize > u32::MAX as usize {
                return ((u32::MAX as u64) << 32) as i64;
            }
            // SAFETY: the host rejects nested generated string-result callins,
            // so this one export has exclusive use of its static result buffer.
            let output = unsafe { core::slice::from_raw_parts_mut(pointer, $bytes) };
            let used = $handler(kind, unit_id, feature_id, ground_pos_x, ground_pos_y, ground_pos_z, output);
            if used > $bytes || used > u32::MAX as usize {
                return ((u32::MAX as u64) << 32) as i64;
            }
            (((used as u64) << 32) | pointer as u32 as u64) as i64
        }
    };
}

